import math

def f(x):
    return x ** 2 + 3 * x + 1

def deriv(fn, x, h=1e-5):
    return (fn(x + h) - fn(x - h)) / (2 * h)

print(round(deriv(f, 2.0), 4))

def g(v):
    return v[0] ** 2 + v[1] ** 2

def gradient(fn, point, h=1e-5):
    grad = []
    for j in range(len(point)):
        ph = [p + (h if i == j else 0) for i, p in enumerate(point)]
        mh = [p - (h if i == j else 0) for i, p in enumerate(point)]
        grad.append((fn(ph) - fn(mh)) / (2 * h))
    return grad

print([round(x, 4) for x in gradient(g, [1.0, 2.0])])
